result:
Extraeré los conceptos formales de esta nota sobre Off-Policy Actor-Critic.

{"concepto": "Importance Weights (pesos de importancia)", "enunciado": "$\\nabla_{\\theta'} J(\\theta') \\approx \\sum_{t,i} \\frac{\\pi_{\\theta'}(a_{i,t} \\mid s_{i,t})}{\\pi_\\theta(a_{i,t} \\mid s_{i,t})} \\nabla_{\\theta'} \\log \\pi_{\\theta'}(a_{t,i} \\mid s_{t,i}) \\hat{A}^{\\pi_\\theta}(s_{t,i}, a_{t,i})$", "problema": "Permitir actualización de política nueva con datos colectados por política vieja", "limite": "Invalidan cuando la política diverge significativamente del datos recolectados; el sesgo crece exponencialmente con el número de pasos", "patron": "Ponderar cada transición por la razón de probabilidades de acción entre la política actual y la de recolección", "linea": 64}
{"concepto": "Generalized Advantage Estimation (GAE, λ)", "enunciado": "$\\hat{A}_t = \\sum_{l=0}^{T-t}(\\gamma \\lambda)^l \\delta_{t+l},\\quad \\delta_t = r_t + \\gamma V(s_{t+1}) - V(s_t)$", "problema": "Estimar ventajas balanceando sesgo y varianza de múltiples pasos", "limite": "λ ∈ [0,1]; valor típico 0.95; requiere función V estable", "patron": "Combinar n-step returns con decaimiento exponencial ponderado, interpolando entre bootstrap inmediato y horizon completo", "linea": 119}
{"concepto": "KL Constraint (restricción de divergencia KL)", "enunciado": "$\\max_{\\theta'} \\tilde{J}(\\theta') \\quad \\text{s.t.} \\quad \\mathbb{E}_{s \\sim \\pi_\\theta}\\left[D_{\\mathrm{KL}}\\left(\\pi_{\\theta'}(\\cdot \\mid s) \\| \\pi_\\theta(\\cdot \\mid s)\\right)\\right] \\leq \\epsilon$", "problema": "Limitar cambio de política mediante restricción explícita de divergencia", "limite": "Requiere resolver problema dual; computacionalmente más costoso que clipping", "patron": "Agregar restricción de desigualdad que encierra la solución en una bola de divergencia KL", "linea": 135}
{"concepto": "PPO Clipping Objective", "enunciado": "$\\tilde{J}(\\theta') = \\sum_{t,i} \\min\\left(\\frac{\\pi_{\\theta'}(a_{i,t} \\mid s_{i,t})}{\\pi_\\theta(a_{i,t} \\mid s_{i,t})} \\hat{A}^{\\pi_\\theta}, \\; \\mathrm{clip}\\left(\\frac{\\pi_{\\theta'}(a_{i,t} \\mid s_{i,t})}{\\pi_\\theta(a_{i,t} \\mid s_{i,t})}, 1-\\epsilon, 1+\\epsilon\\right) \\hat{A}^{\\pi_\\theta}\\right)$", "problema": "Permitir múltiples pasos de gradient sin que la política se aleje demasiado", "limite": "ε típico 0.1-0.2; requiere estimar ventajas confiables; clip muy loose pierde efecto", "patron": "Usar min con versión clipeada del ratio para eliminar incentivos de desviación extrema", "linea": 143}
{"concepto": "TD Update (Temporal Difference para Q-función)", "enunciado": "$\\min_\\phi \\sum_{(s,a,s') \\in \\mathcal{D}} \\left\\| \\hat{Q}^\\pi_\\phi(s, a) - \\left(r(s,a) + \\gamma \\mathbb{E}_{a' \\sim \\pi_\\theta(\\cdot|s')}\\left[\\hat{Q}^\\pi_{\\phi'}(s', a')\\right]\\right)\\right\\|^2$", "problema": "Aprender valores Q de acción usando datos off-policy sin sesgo", "limite": "Converge solo cuando valores futuros son mejores estimados; diverge si Q target es sesgado", "patron": "Minimizar MSE entre predicción Q(s,a) y target bootstrap compuesto por reward + V descuentado", "linea": 172}
{"concepto": "SAC Objective (entropy regularization)", "enunciado": "$\\max_\\theta \\mathbb{E}_{s \\sim \\mathcal{D}, a \\sim \\pi_\\theta(\\cdot|s)} \\left[\\hat{Q}^\\pi(s, a) - \\alpha \\log \\pi_\\theta(a \\mid s)\\right]$", "problema": "Balancear explotación de Q-valores con exploración manteniendo entropía de política", "limite": "α debe escalarse con dimensión de acción; valores muy altos hacen política uniforme", "patron": "Agregar término de entropía negativa ponderado al objetivo de maximización de valor", "linea": 181}
{"concepto": "Potential-based Reward Shaping (dar forma a rewards)", "enunciado": "$F(s, a, s') = \\gamma \\Phi(s') - \\Phi(s)$", "problema": "Añadir rewards que guíen aprendizaje sin cambiar política óptima", "limite": "Φ debe diseñarse según estructura MDP; shaping incorrecto causa reward hacking", "patron": "Agregar término de diferencia de función potencial entre estados que preserva política óptima", "linea": 315}
{"concepto": "Prioritized Experience Replay (muestreo priorizado)", "enunciado": "Transiciones muestreadas con probabilidad proporcional a $|\\delta_t|^\\alpha$ (TD error), corregidas con importance sampling weight $\\left(\\frac{1}{N} \\frac{1}{p_i}\\right)^\\beta$ donde $\\beta$ crece de 0.4 a 1.0", "problema": "Mejorar eficiencia de muestreo del replay buffer enfocándose en transiciones con alto error", "limite": "Puede amplificar ruido si prioridades se basan en estimados ruidosos; requiere IS correction", "patron": "Muestrear con probabilidad proporcional a métrica de importancia, corregir sesgo con pesos inversos", "linea": 248}
{"concepto": "Target Smoothing (Polyak averaging)", "enunciado": "Usar coeficiente $\\tau$ para actualizar red target: $\\phi' \\leftarrow \\tau \\phi + (1-\\tau) \\phi'$ (típico $\\tau=0.005$)", "problema": "Estabilizar predicciones de valores Q en aprendizaje off-policy evitando cambios abruptos", "limite": "τ muy pequeño: convergencia lenta; τ grande: inestabilidad por cambios rápidos", "patron": "Actualizar parámetros target de red como promedio móvil ponderado de red principal", "linea": 306}
{"concepto": "Reward Clipping (normalización de rewards)", "enunciado": "Limitar rewards a rango $[-1, 1]$", "problema": "Prevenir gradientes explosivos y escalar signals numéricas consistentemente", "limite": "Suprime información sobre magnitud relativa de rewards", "patron": "Normalizar señales numéricas de entrada a rango acotado para estabilidad numérica", "linea": 307}
{"concepto": "Value Normalization (normalización de valores)", "enunciado": "Normalizar valores Q a nivel batch usando estadísticas de población", "problema": "Reducir drift de escala en predicciones de valor durante entrenamiento off-policy", "limite": "Requiere estadísticas batch válidas; pierde información de magnitud absoluta", "patron": "Estandarizar salidas de red usando media y varianza observadas en mini-batch", "linea": 308}
